using System;
using System.Drawing;
using System.Runtime.InteropServices;

public class Thumb {
    [ComImport, Guid("bcc18b79-ba16-442f-80c4-8a59c30c463b"), InterfaceType(ComInterfaceType.InterfaceIsIUnknown)]
    interface IShellItemImageFactory {
        void GetImage([In, MarshalAs(UnmanagedType.Struct)] SIZE size, [In] int flags, [Out] out IntPtr phbm);
    }
    [StructLayout(LayoutKind.Sequential)]
    public struct SIZE { public int cx; public int cy; }
    [DllImport("shell32.dll", CharSet = CharSet.Unicode, PreserveSig = false)]
    static extern void SHCreateItemFromParsingName([In] string pszPath, IntPtr pbc, [In, MarshalAs(UnmanagedType.LPStruct)] Guid riid, [Out, MarshalAs(UnmanagedType.Interface)] out IShellItemImageFactory ppv);

    public static void SaveThumb(string videoPath, string outJpg) {
        IShellItemImageFactory fac;
        SHCreateItemFromParsingName(videoPath, IntPtr.Zero, new Guid("bcc18b79-ba16-442f-80c4-8a59c30c463b"), out fac);
        IntPtr hbmp;
        fac.GetImage(new SIZE { cx = 640, cy = 360 }, 0, out hbmp);
        using (Bitmap bmp = Image.FromHbitmap(hbmp)) {
            bmp.Save(outJpg, System.Drawing.Imaging.ImageFormat.Jpeg);
        }
    }
}
